 * Unit tests for ArrayUtils.add(T[] array, int index, T element)
 */
public class ArrayUtils_add_TriageGen2Test {











    @Test
    public void testAdd_NullArray_NullElement() {
        // Covers the branch: else { return (T[]) new Object[] { null }; }
        // Note: Due to type erasure and the specific implementation provided, 
        // this returns an Object array containing null.
        Object[] result = ArrayUtils.add(null, 0, null);
        assertNotNull(result);
        assertEquals(1, result.length);
        assertNull(result[0]);
    }








